import{_ as t,o as r,c as e,a2 as l}from"./chunks/framework.wVcpyw2-.js";const c=JSON.parse('{"title":"闲置交易","description":"闲置交易：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/idle.md","filePath":"features/idle.md","lastUpdated":1785051348000}'),i={name:"features/idle.md"};function o(n,a,s,d,h,u){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="闲置交易" tabindex="-1">闲置交易 <a class="header-anchor" href="#闲置交易" aria-label="Permalink to &quot;闲置交易&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按区域开启闲置物品发布与交易，并配置展示规则、联系方式与交易约束。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>目标区域已创建。</li><li>文件存储可用（闲置商品图）。</li><li>若涉及在线付款，需配置 <a href="/features/payment">支付与提现</a>。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>路径：<strong>区域管理 → 闲置配置</strong></p><p>在列表中选择 <strong>平台默认</strong> 或具体区域，编辑：</p><ul><li>是否启用闲置模块</li><li>发布字段要求（价格、成色、交易方式等，以页面为准）</li><li>是否需审核后展示</li><li>联系方式展示规则（私信 / 电话等）</li></ul><p>保存后对应该区域立即生效（客户端需刷新或重新进入页面）。</p><h3 id="内容管理" tabindex="-1">内容管理 <a class="header-anchor" href="#内容管理" aria-label="Permalink to &quot;内容管理&quot;">​</a></h3><p>用户发布的闲置信息可在以下位置监管：</p><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>社交圈子 → 笔记管理</strong></td><td>部分闲置以笔记形式展示时可统一下架</td></tr><tr><td><strong>用户体系 → 平台举报</strong></td><td>处理违规闲置信息</td></tr></tbody></table><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>闲置为 <strong>纯区域级</strong> 功能：<strong>区域管理 → 闲置配置</strong> 中每一行对应一个 region_id。</p><ul><li>平台默认：新区域未单独配置时的兜底</li><li>某区域关闭闲置：仅编辑该区域行并关闭启用开关</li></ul><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在 <strong>闲置配置</strong> 中开启测试区域。</li><li>客户端切换至该区域，出现闲置发布入口，成功发布一条带图闲置。</li><li>关闭该区域闲置后，入口隐藏或提示功能未开放。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>没有闲置入口</strong></p><ul><li><strong>闲置配置</strong> 中该区域未启用。</li><li><strong>UI管理 → TabBar配置 / 页面配置</strong> 未展示闲置 Tab。</li></ul><p><strong>无法上传图片</strong></p><ul><li>检查 <a href="/features/storage">文件存储</a> 与 <strong>笔记配置</strong> 中的图片相关限制。</li></ul><p><strong>交易纠纷</strong></p><ul><li>平台通常仅提供信息展示；在线支付订单可在 <strong>财务管理 → 资金交易</strong> 查流水，结合 <strong>平台举报</strong> 处理。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/region">区域管理</a></li><li><a href="/features/payment">支付与提现</a></li></ul>',27)])])}const p=t(i,[["render",o]]);export{c as __pageData,p as default};
